				Password: "password123",
			},

args.command:
find /bench/repo -name '*.go' ! -path '*/proto/gen/*' ! -name '*.pb.go' -print | while read -r f; do
  awk -v file="${f#/bench/repo/}" '
    /^func / {
      if (match($0, /^func \(([^)]+)\) ([^(]+)\(/, m)) {
        recv = m[1]; fname = m[2]
        n = split(recv, parts, " ")
        rtype = parts[n]
        sub(/^\*/, "", rtype)
        caller = "(" rtype ")." fname
      } else if (match($0, /^func ([^(]+)\(/, m)) {
        caller = m[1]
      }
    }
    /\.Store\.GetUser\(|\.store\.GetUser\(|stores\.GetUser\(|\<ts\.GetUser\(|\<s\.GetUser\(/ {
      if ($0 ~ /Service\.GetUser\(|APIV1Service\.GetUser\(|client\.GetUser\(|server\.GetUser\(|\.GetUser\(\)|\<d\.GetUser\(/) next
      if (caller ~ /^GetUser$/ && file ~ /^store\/user\.go$/) next
      if (caller != "") print caller "\t" file
    }
  ' "$f"
done | sort -u

